function EXTRA(R,ICON){
 /* hook: the spec page and the finished chip */
 ICON.vdSpec=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${VD_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${VD_T(20,38,'spec: one written page',{fs:24,fw:800,fill:BLU})}${[['function','meter control'],['clock','50 MHz'],['power','mW budget']].map(([a,v],i)=>VD_T(28,76+i*30,a,{fs:22,fw:700})+VD_T(356,76+i*30,v,{fs:22,a:'end',fill:'#5C6577'})).join('')}</g>`;
 ICON.vdChip=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${VD_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${VD_box(30,30,100,100,{fill:'#343A40',st:'#343A40',r:6})}${[0,1,2,3,4].map(k=>VD_L(40+k*20,30,40+k*20,18,'#868E96',3)+VD_L(40+k*20,130,40+k*20,142,'#868E96',3)).join('')}${[...Array(6).keys()].map(i=>[...Array(6).keys()].map(j=>`<rect x="${38+i*15}" y="${38+j*15}" width="10" height="10" fill="#FFC078"/>`).join('')).join('')}${VD_T(150,74,'millions of',{fs:26,fw:800,fill:ORG})}${VD_T(150,108,'gates',{fs:26,fw:800,fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.vdFlow=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${VD_row(0,20,128,56,18,['Front end','netlist'],{each:[{},{st:BLU,fill:'#E7F5FF',fc:BLU}]})}${VD_arrow(210,78,210,124,'#5C6577',2.5)}${VD_row(146,126,128,56,18,['Back end','tapeout'],{st:GRN,each:[{st:GRN},{st:GRN,fill:'#EBFBEE',fc:GRN}]})}${VD_box(0,232,420,60,{fill:'#E7F5FF',st:BLU,sw:2.5,r:10,ex:'stroke-dasharray="9 6"'})}${VD_T(210,270,'verification beside it all',{fs:24,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.vdScan=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${VD_T(0,30,'one chain: L = 5,000',{fs:24,fw:800,fill:TRED})}<rect x="0" y="48" width="420" height="30" rx="6" fill="${TPINK}" stroke="${TRED}" stroke-width="2.5"/>${VD_T(0,132,'ten chains: L = 500',{fs:24,fw:800,fill:GRN})}${[0,1,2,3,4].map(k=>`<rect x="0" y="${150+k*28}" width="84" height="20" rx="5" fill="#EBFBEE" stroke="${GRN}" stroke-width="2.5"/>`).join('')}${VD_T(110,206,'…',{fs:28,fw:800,fill:GRN})}${VD_T(420,236,'100.12 → 10.03 ms',{fs:24,fw:800,a:'end',fill:GRN})}${VD_T(420,280,'shift in parallel',{fs:22,a:'end',fill:'#5C6577'})}</g>`;
 ICON.vdCost=(x,y)=>{const px=n=>20+0.038*n, py=l=>280-1.3*l, N=[0,10000], nb=4e6/1300;
  return `<g transform="translate(${x-210} ${y-165})">${VD_arrow(20,280,420,280,'#868E96',2)}${VD_arrow(20,280,20,20,'#868E96',2)}${VD_poly(N.map(n=>[px(n),py(VD_fpga(n))]),ORG,5)}${VD_poly(N.map(n=>[px(n),py(VD_ga(n))]),BLU,5)}${VD_T(px(9600),py(VD_fpga(9600))+6,'FPGA',{fs:24,fw:800,fill:ORG,a:'end'})}${VD_T(px(10000),py(VD_ga(10000))+36,'gate array',{fs:24,fw:800,fill:BLU,a:'end'})}<circle cx="${px(nb).toFixed(1)}" cy="${py(VD_fpga(nb)).toFixed(1)}" r="12" fill="${GRN}" stroke="#FFFFFF" stroke-width="3"/>${VD_T(px(nb)-6,py(VD_fpga(nb))-60,'break-even',{fs:24,fw:800,fill:GRN})}${VD_T(px(nb)-6,py(VD_fpga(nb))-30,'3,077 chips',{fs:24,fw:800,fill:GRN})}${VD_T(420,316,'chips',{fs:22,a:'end',fill:'#5C6577'})}</g>`};
}
